import random

def is_triangle(g, p, o):
    return g + p > o and g + o > p and p + o > g

def get_non_triangles(n, tris_with_colors):
    gs = sorted([t[0] for t in tris_with_colors], reverse=True)
    ps = sorted([t[1] for t in tris_with_colors], reverse=True)
    os = sorted([t[2] for t in tris_with_colors], reverse=True)
    non_triangles = 0
    for i in range(n):
        if not is_triangle(gs[i], ps[i], os[i]):
            non_triangles += 1
    return non_triangles

def solve_for_n(n, iterations=1000000):
    max_non = 0
    for _ in range(iterations):
        tris_with_colors = []
        for _ in range(n):
            # More varied triangle generation
            mode = random.randint(0, 1)
            if mode == 0:
                a, b, c = random.randint(1, 100), random.randint(1, 100), random.randint(1, 100)
                # Ensure it's a triangle
                if a + b <= c or a + c <= b or b + c <= a:
                    continue
            else:
                # Create a very "thin" triangle
                a = random.randint(100, 200)
                b = random.randint(100, 200)
                c = a + b - random.randint(1, 10)
            tris_with_colors.append(random.sample([a, b, c], 3))

        if len(tris_with_colors) < n:
            continue

        max_non = max(max_non, get_non_triangles(n, tris_with_colors))
        if max_non == n - 1:
            return max_non
    return max_non

for n in range(1, 11):
    print(f"n={n}: {solve_for_n(n)}")

